alter table enquiries add column if not exists status text not null default 'new';
alter table enquiries add column if not exists enquiry_type text not null default 'General Inquiry';
insert into enquiries (name,email,phone,subject,message,status,enquiry_type) select * from (values ('Ruwan Silva','ruwan.silva@example.com','+94 77 123 4567','Availability','Hi, I would like to know the availability for 14 November.','new','Availability'),('Priya Mendis','priya.mendis@example.com','+94 76 987 6543','Rates & Pricing','Could you please share the rates for December?','responded','Rates & Pricing'),('Dilshan Perera','dilshan.perera@example.com','+94 77 456 7890','Booking Inquiry','We are planning a family trip to Nuwara Eliya.','in_progress','Booking Inquiry'),('Nimali Fernando','nimali.fernando@example.com','+94 77 654 3210','General Inquiry','Do you have parking available at the property?','responded','General Inquiry'),('Saman Jayasuriya','saman.jayasuriya@example.com','+94 71 234 5678','Availability','Is the apartment available for the last week of December?','converted','Availability')) v(name,email,phone,subject,message,status,enquiry_type) where not exists(select 1 from enquiries where email=v.email and subject=v.subject);
